ired this.updatedAt,    required this.imageUrl,  });  final int id;  final int productId;  final String image;  final String imageUrl;  final int isPrimary;  final DateTime? createdAt;  final DateTime? updatedAt;  factory PrimaryImage.fromJson(Map<String, dynamic> json){    return PrimaryImage(      id: json["id"] ?? 0,      productId: json["product_id"] ?? 0,      image: json["image"] ?? "",      imageUrl: json["image_url"] ?? "",      isPrimary: json["is_primary"] ?? 0,      createdAt: DateTime.tryParse(json["created_at"] ?? ""),      updatedAt: DateTime.tryParse(json["updated_at"] ?? ""),    );  }  Map<String, dynamic> toJson() => {    "id": id,    "product_id": productId,    "image": image,    "image_url": imageUrl,    "is_primary": isPrimary,    "created_at": createdAt?.toIso8601String(),    "updated_at": updatedAt?.toIso8601String(),  };}